        if self.CurrentState == self.GameState.Playing or self.CurrentState == self.GameState.Paused then
            if not UIViewMgr:IsViewVisible(UIViewID.StarLightRhythmGameMainView) then
                UIViewMgr:ShowView(UIViewID.StarLightRhythmGameMainView)
